1757	Result<DocPtrMap> CollectionImpl::Fetch(
1758	    const std::vector<std::string> &pks,
1759	    const std::optional<std::vector<std::string>> &output_fields,
1760	    bool include_vector) const {
1761	  std::shared_lock lock(schema_handle_mtx_);
1762	
1763	  CHECK_DESTROY_RETURN_STATUS_EXPECTED(destroyed_, false);
1764	
1765	  auto segments = get_all_segments();
1766	
1767	  DocPtrMap results;
1768	
1769	  for (auto &pk : pks) {
1770	    uint64_t doc_id;
1771	    bool has = id_map_->has(pk, &doc_id);
1772	    if (!has) {
1773	      results.insert({pk, nullptr});
1774	      continue;
1775	    }
1776	    if (delete_store_->is_deleted(doc_id)) {
1777	      results.insert({pk, nullptr});
1778	      continue;
1779	    }
1780	    auto segment = local_segment_by_doc_id(doc_id, segments);
1781	    if (!segment) {
1782	      LOG_WARN("doc_id: %zu segment not found", (size_t)doc_id);
1783	      results.insert({pk, nullptr});
1784	      continue;
1785	    }
1786	    results.insert({pk, segment->Fetch(doc_id, output_fields, include_vector)});
1787	  }
1788	
1789	  return results;
1790	}
