1134	Status CollectionImpl::AddColumn(const FieldSchema::Ptr &column_schema,
1135	                                 const std::string &expression,
1136	                                 const AddColumnOptions &options) {
1137	  CHECK_COLLECTION_READONLY_RETURN_STATUS;
1138	
1139	  std::lock_guard lock(schema_handle_mtx_);
1140	
1141	  CHECK_DESTROY_RETURN_STATUS(destroyed_, false);
1142	
1143	  // validate
1144	  auto s = validate("", column_schema, expression, "", ColumnOp::ADD);
1145	  CHECK_RETURN_STATUS(s);
1146	
1147	  // forbidden writing until index is ready
1148	  std::lock_guard write_lock(write_mtx_);
1149	
1150	  auto new_schema = std::make_shared<CollectionSchema>(*schema_);
1151	  s = new_schema->add_field(column_schema);
1152	  CHECK_RETURN_STATUS(s);
1153	
1154	  if (writing_segment_->doc_count() > 0) {
1155	    s = switch_to_new_segment_for_writing();
1156	    CHECK_RETURN_STATUS(s);
1157	  }
1158	
1159	  Version new_version = version_manager_->get_current_version();
1160	
1161	  // add column on segment manager
1162	  s = segment_manager_->add_column(column_schema, expression,
1163	                                   options.concurrency_);
1164	  CHECK_RETURN_STATUS(s);
1165	
1166	  // reset writing segment with new schema
1167	  auto id = writing_segment_->id();
1168	  auto min_doc_id = writing_segment_->meta()->min_doc_id();
1169	
1170	  s = writing_segment_->destroy();
1171	  CHECK_RETURN_STATUS(s);
1172	  writing_segment_.reset();
1173	
1174	  SegmentOptions seg_options;
1175	  seg_options.enable_mmap_ = options_.enable_mmap_;
1176	  seg_options.max_buffer_size_ = options_.max_buffer_size_;
1177	  seg_options.read_only_ = options_.read_only_;
1178	  auto writing_segment =
1179	      Segment::CreateAndOpen(path_, *new_schema, id, min_doc_id, id_map_,
1180	                             delete_store_, version_manager_, seg_options);
1181	  if (!writing_segment) {
1182	    return writing_segment.error();
1183	  }
1184	  writing_segment_ = writing_segment.value();
1185	
1186	  // update new version
1187	  new_version.set_schema(*new_schema);
1188	  new_version.reset_writing_segment_meta(writing_segment_->meta());
1189	
1190	  auto new_segment_metas = segment_manager_->get_segments_meta();
1191	  for (auto meta : new_segment_metas) {
1192	    s = new_version.update_persisted_segment_meta(meta);
1193	    CHECK_RETURN_STATUS(s);
1194	  }
1195	
1196	  s = version_manager_->apply(new_version);
1197	  CHECK_RETURN_STATUS(s);
1198	
1199	  // persist manifest
1200	  s = version_manager_->flush();
1201	  CHECK_RETURN_STATUS(s);
1202	
1203	  schema_ = new_schema;
1204	
1205	  return Status::OK();
1206	}
